/* =========================================================
 *  DEMANDAS RECORRENTES (mesma lógica do servidor)
 * ========================================================= */
const DSEM=['dom','seg','ter','qua','qui','sex','sab'],DSEM_NOME=['domingo','segunda-feira','terça-feira','quarta-feira','quinta-feira','sexta-feira','sábado'];
function semAc(s){return String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').trim().toLowerCase()}
function dSem(s){return parseISO(s).getDay()}
function recVence(r,d){
  const base=r.inicio||'';if(base&&d<base)return false;
  const wd=DSEM.indexOf(semAc(r.dia).slice(0,3));
  switch(r.freq){
    case 'Diária':return true;
    case 'Semanal':case 'Quinzenal':{const passo=r.freq==='Semanal'?7:14;
      if(!base)return passo===7&&wd>=0&&dSem(d)===wd;
      let an=base;if(wd>=0)while(dSem(an)!==wd)an=addDias(an,1);
      const df=diasEntre(an,d);return df>=0&&df%passo===0}
    case 'Mensal':{const alvo=Number(r.dia)||(base?Number(base.slice(8,10)):0);if(!alvo)return false;
      const [a,m,dd]=d.split('-').map(Number);return dd===Math.min(alvo,new Date(a,m,0).getDate())}
    case 'Personalizada':{const n=Math.floor(Number(r.aCada));if(!base||!(n>=1))return false;return diasEntre(base,d)%n===0}
  }
  return false;
}
function recProximas(r,desde,qtd){const o=[];let d=desde;for(let i=0;i<800&&o.length<qtd;i++){if(recVence(r,d))o.push(d);d=addDias(d,1)}return o}
function recTexto(r){
  const base=r.inicio||'',wt=DSEM.indexOf(semAc(r.dia).slice(0,3)),wd=wt>=0?wt:base?dSem(base):-1,nd=wd>=0?DSEM_NOME[wd]:'',todo=wd===0||wd===6?'Todo ':'Toda ';
  switch(r.freq){
    case 'Diária':return 'Todos os dias';
    case 'Semanal':return nd?todo+nd:'Semanal';
    case 'Quinzenal':return 'A cada 2 semanas'+(nd?` (${nd})`:'');
    case 'Mensal':{const dm=Number(r.dia)||(base?Number(base.slice(8,10)):0);return dm?`Todo dia ${dm} do mês`+(dm>28?' (ou o último dia)':''):'Mensal'}
    case 'Personalizada':{const n=Math.floor(Number(r.aCada));return n===1?'Todos os dias':`A cada ${n} dias`}
  }
  return r.freq||'—';
}
function ehRecorrente(t){const o=String(t.origem||'');return o.indexOf('rec:')===0||o==='recorrente'}
function recDe(t){const o=String(t.origem||'');if(o.indexOf('rec:')!==0)return null;const id=o.split(':')[1];return (S.recs||[]).find(r=>r.id===id)||null}
function podeRec(r){return r&&(gestor()||(S.me&&(r.criadoPor===S.me.nome||r.responsavel===S.me.nome)))&&perfil()!=='Leitor'}
function lerRepForm(){
  const f=$('nRep')&&$('nRep').value;if(!f)return null;
  const inicio=$('nIni').value||hojeISO();
  if(inicio<hojeISO())return {erro:'A data de início não pode ser no passado'};
  const aCada=f==='Personalizada'?Math.floor(Number($('nRepN').value)):'';
  if(f==='Personalizada'&&!(aCada>=1&&aCada<=365))return {erro:'Informe de quantos em quantos dias (1 a 365)'};
  const prazo=$('nPrazo').value;
  if(prazo&&prazo<inicio)return {erro:'O prazo precisa ser no mesmo dia ou depois do início'};
  return {freq:f,aCada,inicio,prazoDias:prazo?diasEntre(inicio,prazo):''};
}
